package esercizi_3;

public class es_2 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub

		/*
		 * Calcolare la somma dei numeri da 1 a 310 utilizzando un ciclo "while".
		 */
		
		int numeroFinale = 0;
	    int i = 1;
	    
	    while (i <= 310) 
	    {
	    	numeroFinale = numeroFinale + i;
	    	i++;
	    }
	    
	    System.out.println("Il numero finale della somma dei numeri da 1 a 310 è: " + numeroFinale);
	}
/*
 * voto 10/10
 */
}
